15	use crate::Qwen35DecodeOverlap;
16	use crate::Qwen35LaunchOptions;
17	use crate::Qwen35SchedulerPolicy;
18	
19	pub static MODEL_LINE: Qwen35Line = Qwen35Line;
20	
21	pub struct Qwen35Line;
22	
23	// Qwen3.5-exclusive CLI flags.
24	#[derive(ClapArgs)]
25	struct Qwen35Cli {
26	    /// Per-rank GPU budget in MiB for joint prefix snapshots; zero disables reuse.
27	    #[arg(long, default_value_t = 0)]
28	    qwen35_prefix_cache_mib: usize,
29	    /// Decode-batch capacity, 1..=64. Qwen3.5 internally rounds allocation to
30	    /// the next graph bucket but admits only this many scheduler slots; defaults
31	    /// to 64.
32	    #[arg(long)]
33	    max_batch: Option<usize>,
34	
35	    /// Qwen3.5 prefill/decode scheduler policy. Defaults to `off`; `auto` is
36	    /// opt-in and currently single-GPU only.
37	    #[arg(long, value_enum, default_value_t = CliQwen35SchedulerPolicy::Off)]
38	    qwen35_scheduler_policy: CliQwen35SchedulerPolicy,
39	}
40	
41	/// CLI selector for the Qwen3.5 adaptive scheduler policy.
42	#[derive(Clone, Copy, Debug, Default, clap::ValueEnum)]
43	enum CliQwen35SchedulerPolicy {
44	    /// Fixed chunked-prefill behavior.
45	    #[default]
46	    Off,
47	    /// Runtime-state adaptive policy.
48	    Auto,
49	}
50	
51	impl CliQwen35SchedulerPolicy {
52	    fn resolve(self) -> Qwen35SchedulerPolicy {
53	        match self {
54	            Self::Off => Qwen35SchedulerPolicy::Off,
55	            Self::Auto => Qwen35SchedulerPolicy::Auto,
56	        }
57	    }
58	}
59	
60	fn cli(ctx: &LaunchContext<'_>) -> Qwen35Cli {
61	    Qwen35Cli::from_arg_matches(ctx.matches).expect("Qwen35Cli parses from the merged command")
62	}
63	
64	fn resolve_decode_overlap(overlap: CliDecodeOverlap) -> Result<Qwen35DecodeOverlap, CliError> {
65	    match overlap {
66	        CliDecodeOverlap::Off => Ok(Qwen35DecodeOverlap::Off),
67	        CliDecodeOverlap::Stream => Ok(Qwen35DecodeOverlap::SharedSm),
68	        CliDecodeOverlap::GreenCtx => Err(CliError::rule(
69	            "Qwen3.5 supports --decode-overlap=off|stream only",
70	        )),
71	    }
72	}
73	
74	impl ModelLine for Qwen35Line {
75	    fn name(&self) -> &'static str {
76	        "Qwen3.5"
77	    }
78	
79	    fn probe(&self, config: &serde_json::Value) -> Result<(), String> {
80	        let model_type = config.get("model_type").and_then(serde_json::Value::as_str);
81	        let text_model_type = config
82	            .get("text_config")
83	            .and_then(|text| text.get("model_type"))
84	            .and_then(serde_json::Value::as_str);
85	        if model_type != Some("qwen3_5") && text_model_type != Some("qwen3_5_text") {
86	            return Err(format!("model_type {model_type:?} is not \"qwen3_5\""));
87	        }
88	        crate::probe_config_json(config).map_err(|error| error.to_string())
89	    }
90	
91	    fn augment_cli(&self, cmd: clap::Command) -> clap::Command {
92	        Qwen35Cli::augment_args(cmd)
93	    }
94	
95	    fn consumed_shared_args(&self) -> &'static [&'static str] {
96	        &[
97	            "device_ordinal",
98	            "tp_size",
99	            "cuda_graph",
100	            "no_prefix_cache",
101	            "max_prefill_tokens",
102	            "decode_overlap",
103	            "decode_sm_pct",
104	        ]
105	    }
106	
107	    fn validate(
108	        &self,
109	        ctx: &LaunchContext<'_>,
110	        _provided: &BTreeSet<String>,
111	    ) -> Result<(), CliError> {
112	        let cli = cli(ctx);
113	        let decode_overlap = resolve_decode_overlap(ctx.shared.decode_overlap)?;
114	        if cli.qwen35_prefix_cache_mib > 0 && ctx.shared.no_prefix_cache {
115	            return Err(CliError::rule(
116	                "--qwen35-prefix-cache-mib and --no-prefix-cache are contradictory",
117	            ));
118	        }
119	        if let Some(max_batch) = cli.max_batch {
120	            if !(1..=crate::MAX_DECODE_BATCH).contains(&max_batch) {
121	                return Err(CliError::rule(format!(
122	                    "--max-batch must be in 1..={} for Qwen3.5, got {max_batch}",
123	                    crate::MAX_DECODE_BATCH
124	                )));
125	            }
126	        }
127	        if decode_overlap != Qwen35DecodeOverlap::Off {
128	            let max_batch = cli.max_batch.unwrap_or(crate::MAX_DECODE_BATCH);
129	            if max_batch > crate::MAX_SHARED_SM_DECODE_BATCH {
130	                return Err(CliError::rule(format!(
131	                    "Qwen3.5 --decode-overlap=stream requires --max-batch <= {}; got {max_batch}",
132	                    crate::MAX_SHARED_SM_DECODE_BATCH
133	                )));
134	            }
135	        }
136	        if ctx.shared.tp_size > 1 && decode_overlap != Qwen35DecodeOverlap::Off {
137	            return Err(CliError::rule(
138	                "--decode-overlap is single-GPU only; tp_size>1 has no prefill/decode overlap",
139	            ));
140	        }
141	        if ctx.shared.tp_size > 1
142	            && matches!(cli.qwen35_scheduler_policy, CliQwen35SchedulerPolicy::Auto)
143	        {
144	            return Err(CliError::rule(
145	                "--qwen35-scheduler-policy=auto is single-GPU only; Qwen3.5 TP uses the fixed off policy",
146	            ));
147	        }
148	        Ok(())
149	    }
150	
151	    fn serve_plan(&self, _ctx: &LaunchContext<'_>) -> Result<ServePlan, CliError> {
152	        Ok(ServePlan {
153	            // Both generations' templates request the Qwen Coder tool syntax,
154	            // but upstream `Auto` matches the model *path* by substring: a
155	            // `Qwen3.8-27B` directory resolves to the JSON `qwen3_json` parser
156	            // (`docs/models/qwen35/support-qwen38.md`). The line knows better
157	            // than the directory name.
158	            auto_tool_call_parser: Some(ParserSelection::Explicit("qwen3_coder".to_string())),
159	            ..Default::default()
160	        })
161	    }
162	
163	    fn launch(&self, ctx: &LaunchContext<'_>) -> anyhow::Result<LaunchedEngine> {
164	        let cli = cli(ctx);
165	        crate::launch_with_options_policy_and_overlap(
166	            ctx.model_path,
167	            Qwen35LaunchOptions {
168	                prefix_cache_mib: cli.qwen35_prefix_cache_mib,
169	                device_ordinal: ctx.shared.device_ordinal,
170	                tp_size: ctx.shared.tp_size,
171	                cuda_graph: ctx.shared.cuda_graph,
172	                max_batch: cli.max_batch.unwrap_or(crate::MAX_DECODE_BATCH),
173	                max_prefill_tokens: ctx
174	                    .shared
175	                    .max_prefill_tokens
176	                    .unwrap_or(crate::DEFAULT_MAX_PREFILL_TOKENS),
177	            },
178	            cli.qwen35_scheduler_policy.resolve(),
179	            resolve_decode_overlap(ctx.shared.decode_overlap)
180	                .map_err(|error| anyhow::anyhow!(error.to_string()))?,
181	        )
182	        .map(LaunchedEngine::Stepped)
183	    }
184	}
