//! Qwen3.5 configuration: validated model geometry, tensor-parallel local
//! geometry, and model-line identity checks.
//!
//! Ownership model (directional boundaries):
//! - [`model`] deserializes raw config and validates into a TP-agnostic
//!   [`Config35`];
//! - [`tp`] depends on [`model`] and produces the validated
//!   [`LocalGeometry`] that downstream code accepts;
//! - [`error`] owns the typed [`ConfigError`] variants.

use anyhow::Result;

mod error;
mod model;
mod tp;

pub(crate) use model::Config35;
pub(crate) use model::LayerType;
pub(crate) use tp::LocalGeometry;
pub(crate) use tp::TensorParallelConfig;

/// Identity check that `json` is a Qwen3.5 config; size and shape validation
/// belong to the config loader.
pub(crate) fn probe_config_json(json: &serde_json::Value) -> Result<()> {
    let model_type = json
        .get("model_type")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("");
    if model_type != "qwen3_5" {
        anyhow::bail!("not a Qwen3.5 config: model_type={model_type}");
    }
    let architectures: Vec<&str> = json
        .get("architectures")
        .and_then(serde_json::Value::as_array)
        .map(|arr| arr.iter().filter_map(serde_json::Value::as_str).collect())
        .unwrap_or_default();
    anyhow::ensure!(
        architectures.contains(&"Qwen3_5ForConditionalGeneration"),
        "Qwen3.5 architectures must contain Qwen3_5ForConditionalGeneration"
    );
    let text_model_type = json
        .get("text_config")
        .and_then(|tc| tc.get("model_type"))
        .and_then(serde_json::Value::as_str)
        .unwrap_or("");
    anyhow::ensure!(
        text_model_type == "qwen3_5_text",
        "Qwen3.5 text_config.model_type must be qwen3_5_text, got {text_model_type}"
    );
    Ok(())
}

//! The pegainfer server binary: pure dispatch over the compiled-in
//! [`ModelLine`]s. Every model-specific flag, rule, and option type lives in
//! its model crate; this file only wires detection, CLI validation, and the
//! serve path selection together.

use std::time::Instant;

use anyhow::Context;
use clap::FromArgMatches;
use log::info;
use pegainfer_core::logging;
use pegainfer_frontend::engine::LaunchedEngine;
use pegainfer_frontend::model_line::DetectError;
use pegainfer_frontend::model_line::LaunchContext;
use pegainfer_frontend::model_line::ModelLine;
use pegainfer_frontend::model_line::ModelLineRegistry;
use pegainfer_frontend::model_line::SharedArgs;
use pegainfer_frontend::model_line::provided_args;

#[cfg(not(target_env = "msvc"))]
#[global_allocator]
static GLOBAL: tikv_jemallocator::Jemalloc = tikv_jemallocator::Jemalloc;

fn model_lines() -> Vec<&'static dyn ModelLine> {
    vec![
        #[cfg(feature = "deepseek-v2-lite")]
        &pegainfer_deepseek_v2_lite::model_line::MODEL_LINE,
        #[cfg(feature = "gemma4")]
        &pegainfer_gemma4::model_line::MODEL_LINE,
        #[cfg(feature = "glm52")]
        &pegainfer_glm52::model_line::MODEL_LINE,
        #[cfg(feature = "k3")]
        &pegainfer_k3::model_line::MODEL_LINE,
        #[cfg(feature = "kimi-k2")]
        &pegainfer_kimi_k2::model_line::MODEL_LINE,
        #[cfg(feature = "qwen3")]
        &pegainfer_qwen3::model_line::MODEL_LINE,
        #[cfg(feature = "qwen35")]
        &pegainfer_qwen35::model_line::MODEL_LINE,
        #[cfg(feature = "qwen4")]
        &pegainfer_qwen4::model_line::MODEL_LINE,
    ]
}

/// One row of [`families`]: a line's feature, the identities its `probe` claims,
/// and whether that line is compiled into this binary.
struct Family {
    feature: &'static str,
    model_types: &'static [&'static str],
    text_model_types: &'static [&'static str],
    compiled: bool,
}

/// Every line the server can be built with, and the identities its `probe`
/// claims.
///
/// This is **a second source of truth by necessity**: the hint exists for the
/// case where the line — and therefore its `probe` — is compiled out, so these
/// strings cannot be read from the line crate. The `qwen4` row is bound to that
/// crate's own `MODEL_TYPE`/`TEXT_MODEL_TYPE` by a test under the feature
/// (`qwen4_hint_identity_matches_the_line_crate`).
///
/// The hint is **identity-only**: it cannot run a compiled-out probe, so it also
/// fires for a variant that probe would refuse — a quantized sibling (its
/// `quantization_config`), tied embeddings, a YaRN rope. It names the feature to
/// rebuild with; it is not a promise that the checkpoint is servable.
fn families() -> [Family; 8] {
    [
        Family {
            feature: "deepseek-v2-lite",
            model_types: &["deepseek_v2"],
            text_model_types: &[],
            compiled: cfg!(feature = "deepseek-v2-lite"),
        },
        Family {
            feature: "gemma4",
            model_types: &["gemma4", "gemma4_unified"],
            text_model_types: &["gemma4_text", "gemma4_unified_text"],
            compiled: cfg!(feature = "gemma4"),
        },
        Family {
            feature: "glm52",
            model_types: &["glm_moe_dsa"],
            text_model_types: &[],
            compiled: cfg!(feature = "glm52"),
        },
        Family {
            feature: "k3",
            model_types: &["kimi_k3"],
            text_model_types: &["kimi_linear"],
            compiled: cfg!(feature = "k3"),
        },
        Family {
            feature: "kimi-k2",
            model_types: &["kimi_k25", "kimi_k2"],
            text_model_types: &["kimi_k2"],
            compiled: cfg!(feature = "kimi-k2"),
        },
        Family {
            feature: "qwen3",
            model_types: &["qwen3"],
            text_model_types: &[],
            compiled: cfg!(feature = "qwen3"),
        },
        Family {
            feature: "qwen35",
            model_types: &["qwen3_5"],
            text_model_types: &["qwen3_5_text"],
            compiled: cfg!(feature = "qwen35"),
        },
        Family {
            feature: "qwen4",
            model_types: &["qwen4_exp"],
            text_model_types: &["qwen4_exp_text"],
            compiled: cfg!(feature = "qwen4"),
        },
    ]
}

